"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6712],{33868:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WorkbenchGuiController","desc":"Drives the Studio-authored `WorkbenchGui` (Ocean Sunset rebuild, see\\n`roblox-gui-prototypes/2026-10-27-workbench-gui-prototype.html`). Opens via a\\nplaced Workbench station\'s `CraftPromptPart` ProximityPrompt (CollectionService\\ntag `Workbench`, shared with the Shredder on the same station Model). Two pages\\nunder a `UIPageLayout`, switched by the `Personal` (CRAFT) and `Recharge` tabs:\\n\\n- **Craft** \u2014 category chips (one per `WorkbenchConfig.Categories`, firing\\n  `Signals.RequestWorkbenchCategory`), the recipe grid built from\\n  `WorkbenchConfig`, and the detail pane. `AcceptButton` sends `ReqCraft`; when\\n  it can\'t, it is disabled and its label states why (locked / which material\\n  is short).\\n- **Recharge** \u2014 owned armor from `ArmorClient`, the selected kind\'s stats and\\n  reserve, and the hold-to-recharge button (Energy kinds only). The hold eases\\n  the fill toward the level the pool Energy can reach while the percent counts\\n  up; releasing early keeps what was filled (the hold fraction goes to\\n  `ReqRechargeArmor`, which spends only that share).\\n\\nBoth pages repaint live on MaterialPool, armor and Tech-unlock changes. Each\\npage repeats Stash/Move, wired via `PlaceableActions`. Size follows the screen\\nthrough `MainContainer.UIScale`: wide = min(W/1920, H/1022); below 0.68 the\\ncompact layout (authored at 844x332, scale clamped to [0.75, 1.5]) applies.","realm":["Client"],"source":{"line":28,"path":"src/StarterPlayer/StarterPlayerScripts/WorkbenchGuiController.client.luau"}}')}}]);